  static const List<Permission> requestLibraryPermissionList = <Permission>[
    Permission.audio,
  ];

  static _R _requestLibraryPermission(
    String method,
    Map<String, String> params,
  ) async {
    try {
      final results = await requestLibraryPermissionList.request();
      final granted = results[Permission.audio]?.isGranted ?? false;
      // Also drive the controller so its state updates.
      await (DebugHooks.libraryController as LibraryController?)
          ?.requestPermission();
      return _ok({
        'granted': granted,
        'audio': results[Permission.audio]?.name,
      });
    } catch (e) {
      return _error('requestLibraryPermission failed: $e');
    }
  }

  static _R _getOverflowReports(
    String method,
    Map<String, String> params,
  ) async {
    final clear = (params['clear'] ?? 'false') == 'true';
    final reports = _overflowReports
        .map<Map<String, Object?>>(Map<String, Object?>.from)
        .toList(growable: false);
    if (clear) _overflowReports.clear();
    return _ok({'reports': reports, 'count': reports.length});
  }

  /// Read a keyed widget's live rendered text and resolved [TextStyle].
  static _R _probeText(String method, Map<String, String> params) async {
    final key = params['key'];
    if (key == null || key.isEmpty) return _error('key parameter required');
    final el = _findElementByKey(key);
    if (el == null) return _error('no widget found with key "$key"');

    RenderObject? ro = el.findRenderObject();
    if (ro is! RenderParagraph) {
      _walkSubtree(el, (e) {
        final r = e.findRenderObject();
        if (r is RenderParagraph) {
          ro = r;
          return true;
        }
        return false;
      }, includeSelf: true);
    }
    final para = ro;
    if (para is! RenderParagraph) {
      return _ok({
        'key': key,
        'widgetType': el.widget.runtimeType.toString(),
        'text': null,
        'note': 'no RenderParagraph under key',
      });
    }

    final plain = para.text.toPlainText();
    final style = para.text.style;
    return _ok({
      'key': key,
      'text': plain,
      'widgetType': el.widget.runtimeType.toString(),
      'style': {
        'fontSize': style?.fontSize,
        'color': style?.color?.toARGB32().toRadixString(16),
        'fontWeight': style?.fontWeight?.value,
        'fontFamily': style?.fontFamily,
        'height': style?.height,
        'letterSpacing': style?.letterSpacing,
      },
      'size': para.hasSize
          ? {'w': para.size.width, 'h': para.size.height}
          : null,
    });
  }

