    String method,
    Map<String, String> params,
  ) async {
    final clear = (params['clear'] ?? 'false') == 'true';
    if (clear) {
      _frameTimings.clear();
      return _ok({'cleared': true});
    }
    final frames = _frameTimings.toList(growable: false);
